/**
 * Jinx Magician + Wraith: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Magician
 * Wiki: https://wiki.bloodontheclocktower.com/Wraith
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { jinxGuessers } from '#lib/core/rules/jinxes/jinx-effects.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Magician + Wraith jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'magician', 'wraith');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('magician')?.name).toBe('Magician');
		expect(data.byId.get('wraith')?.name).toBe('Wraith');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['magician', 'wraith'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['magician'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['wraith'])).not.toContain(jinx);
	});

	const ids = ['magician', 'wraith', 'chef', 'empath', 'imp'];
	const base = scenario(ids, { script: scriptOf(ids) });
	const guesses = (s: Scenario) => jinxGuessers(s.game, s.characters);
	const alerts = (s: Scenario) =>
		nightStepAlerts(s.game, 'imp', s.characters).filter((a) => a.kind === 'guessed');

	describe('after each execution, the living Magician may guess the Wraith', () => {
		it("is data in the Magician's rules", () => {
			// Wiki: "After each execution, the living Magician may publicly guess a living player as the Wraith. If correct, the Demon must choose the Wraith tonight."
			expect(ownJinxRules(base.game, 'magician', 'wraith', base.characters)).toEqual({
				guessesPartner: { when: ['self-alive', 'after-execution'] }
			});
		});

		it('lets the Magician guess once someone has been executed today', () => {
			// Wiki: "After each execution, the living Magician may publicly guess a living player as the Wraith."
			expect(guesses(base)).toEqual([]);
			const s = base.execute('chef');
			expect(guesses(s)).toEqual([
				{
					seatId: s.seat('magician'),
					owner: 'magician',
					partner: 'wraith',
					partnerSeats: [s.seat('wraith')]
				}
			]);
		});

		it('says at the Demon step that a right guess makes the Demon choose the Wraith', () => {
			// Wiki: "If correct, the Demon must choose the Wraith tonight."
			const s = base.execute('chef');
			expect(alerts(s)).toMatchObject([
				{ kind: 'guessed', seatId: s.seat('magician'), partner: 'wraith' }
			]);
		});

		it('gives a dead Magician no guess, nor one with no living Wraith', () => {
			// Wiki: "the living Magician may publicly guess a living player as the Wraith"
			expect(guesses(base.dies('magician').execute('chef'))).toEqual([]);
			expect(guesses(base.dies('wraith').execute('chef'))).toEqual([]);
		});
	});
});
